# -- breaking-change witnesses ----------------------------------------------
#
# A witness turns a breaking verdict into something the existing ``check``
# can verify out of hand: a concrete JSON object that the accepting
# revision's check reports clean and that the rejecting revision's check
# reports at least one error for. The record is built by walking the
# accepting tree the same way ``check`` walks it - every field a required
# entry names, one value per observed type branch, array elements covering
# every element kind, recursively - so it satisfies every requirement the
# accepting side knows about. The rejecting walk is then layered on top of
# that record, and at the first shape the rejecting side cannot accept the
# current value is left in place: a removed field stays on the record, a
# newly required one is never added, a dropped type keeps its value.
#
# Because the construction mirrors check structurally rather than guessing
# a minimal record, it still settles a demonstrable rejection when other
# branches can only be described approximately: such branches simply stop
# contributing values on the rejecting side, but the exact breaking branch
# keeps its witness. Only a verdict of breaking ever carries a witness;
# compatible and unknown directions report null, and nothing is fabricated
# when no rejection can be demonstrated.


def _witness_value(node: dict) -> Any:
    """One concrete value accepted by a schema node.

    Objects carry every required field; arrays carry one element per
    observed element kind (empty when the schema observed no element
    types, which check then accepts as well). Scalars use distinct fixed
    values per kind so a boolean is never mistaken for a number and null
    is an explicit value rather than a missing field.
    """
    kind = node["kind"]
    if kind == "null":
        return None
    if kind == "boolean":
        return True
    if kind == "number":
        return 1
    if kind == "string":
        return "s"
    if kind == "array":
        return [
            _witness_value(child)
            for child in (node.get("elements") or {}).values()
        ]
    return _witness_object(node, set())


def _witness_object(node: dict, excluded: set[str]) -> dict:
    """A concrete object accepted by an object node.

    Every required exact field receives one value per observed kind; names
    in ``excluded`` are deliberately omitted (a field the rejecting side
    requires that the accepting object is being built without). Overflow
    entries contribute nothing: their folded names and accepted value
    shapes cannot be attributed exactly, so no value is invented for them.
    """
    record: dict[str, Any] = {}
    if _is_collapsed(node):
        return record
    for name, entry in node["fields"].items():
        if name in excluded or entry["optional"]:
            continue
        values = [
            _witness_value(child) for child in entry["types"].values()
        ]
        record[name] = values[0] if len(values) == 1 else values
    return record


class _WitnessBuilder:
    """Builds a check-verifiable record witnessing one breaking direction.

    ``accepted`` is the snapshot whose records are legal (the record is
    built to pass its check); ``rejected`` is the snapshot that must reject
    the record. The walk stays aligned with the two trees exactly the way
    the compatibility diff aligns them, so every value it keeps is on a
    branch the accepting side really accepts.
    """

    def __init__(self, accepted: dict, rejected: dict) -> None:
        self.accepted = accepted
        self.rejected = rejected

    def build(self) -> dict:
        return self.build_object(self.accepted, self.rejected, set())

    def build_object(
        self, accepted: dict, rejected: dict, excluded: set[str]
    ) -> dict:
        record: dict[str, Any] = {}
        # A depth-capped accepting object tracked no fields, so check
        # accepts any object beneath it, including the empty one.
        if _is_collapsed(accepted):
            return record
        rejected_collapsed = _is_collapsed(rejected)
        rejected_fields = {} if rejected_collapsed else rejected["fields"]
        rejected_overflow = None if rejected_collapsed else rejected.get(
            "overflow"
        )
        for name, entry in accepted["fields"].items():
            if name in excluded or entry["optional"]:
                continue
            other = rejected_fields.get(name)
            if other is None:
                # The field is not an exact field of the rejecting object.
                if _overflow_routes(rejected_overflow, name):
                    # The rejecting overflow entry accepts the name under an
                    # only-approximate type set: check it against that
                    # widened set so its values keep passing while the
                    # breaking witness rides on a different branch.
                    other = rejected_overflow
                else:
                    # Removed/unknown field on the rejecting side: keep a
                    # value the accepting side accepts and check reports it
                    # unexpected.
                    record[name] = self._accepted_value(entry)
                    continue
            value = self.build_entry(entry, other)
            if value is not _WITNESS_OMIT:
                record[name] = value
        return record

    @staticmethod
    def _accepted_value(entry: dict) -> Any:
        values = [_witness_value(child) for child in entry["types"].values()]
        return values[0] if len(values) == 1 else values

    def build_entry(self, accepted: dict, rejected: dict) -> Any:
        # An approximate accepting entry cannot be settled exactly; its
        # branch cannot witness the rejection by itself. An approximate
        # rejecting entry still validates (its type set only widens), so
        # values flow through the type-set merge below.
        if accepted.get("approximate"):
            return _WITNESS_OMIT
        values = [
            self.build_type(kind, child, rejected["types"].get(kind))
            for kind, child in accepted["types"].items()
        ]
        values = [value for value in values if value is not _WITNESS_OMIT]
        if not values:
            return _WITNESS_OMIT
        return values[0] if len(values) == 1 else values

    def build_type(
        self, kind: str, accepted_node: dict, rejected_node: dict | None
    ) -> Any:
        if rejected_node is None:
            # The accepting type set contains this kind and the rejecting
            # one does not: keep a value of exactly this kind.
            return _witness_value(accepted_node)
        if kind in ("null", "boolean", "number", "string"):
            return _witness_value(accepted_node)
        if kind == "object":
            return self.build_object(accepted_node, rejected_node, set())
        return self.build_array(accepted_node, rejected_node)

    def build_array(self, accepted: dict, rejected: dict) -> list:
        elements: list[Any] = []
        for kind, child in accepted["elements"].items():
            other = rejected["elements"].get(kind)
            if other is None:
                # The element kind is absent from the rejecting element
                # type set; one such element is enough to fail check.
                elements.append(_witness_value(child))
            elif child["kind"] in ("null", "boolean", "number", "string"):
                elements.append(_witness_value(child))
            elif child["kind"] == "object":
                elements.append(self.build_object(child, other, set()))
            else:
                elements.append(self.build_array(child, other))
        return elements


_WITNESS_OMIT = object()


def _direction_witness(
    verdict: str,
    accepted_root: dict,
    rejected_root: dict,
    accepted_revision: int,
    rejected_revision: int,
    read_check: Any,
) -> dict | None:
    """The witness object for one breaking direction, else ``None``.

    ``read_check(revision, record)`` runs the real ``Lens.check`` against
    one committed snapshot, so both halves of the witness are verified with
    the exact validation the lens exposes rather than a copy of it.
    """
    if verdict != _BREAKING:
        return None
    record = _WitnessBuilder(accepted_root, rejected_root).build()
    if read_check(accepted_revision, record):
        # Internal guard: a witness must pass the accepting revision's
        # check. Never report a counterexample that does not verify.
        raise SchemaConflict("could not build a valid compatibility witness")
    reports = read_check(rejected_revision, record)
    if not reports:
        # The breaking verdict promised a rejection; if the constructed
        # record happens to be accepted (an approximate branch), no witness
        # is fabricated.
        return None
    return {"record": record, "reports": reports}


def _witness_report(
    old_revision: int,
    new_revision: int,
    old_root: dict,
    new_root: dict,
    read_check: Any,
) -> dict:
    """The full compat report plus verifiable breaking-change witnesses."""
    report = _compat_report(old_revision, new_revision, old_root, new_root)
    # Backward: are old-legal records still accepted by the new revision?
    # A breaking verdict is witnessed by a record old check accepts and new
    # check rejects; forward simply swaps the two roles.
    report["witnesses"] = {
        "backward": _direction_witness(
            report["backward"],
            old_root,
            new_root,
            old_revision,
            new_revision,
            read_check,
        ),
        "forward": _direction_witness(
            report["forward"],
            new_root,
            old_root,
            new_revision,
            old_revision,
            read_check,
        ),
    }
    return report

